   54+     class BattleGroundChatBuilder
   55+     {
   56+         public:
   57+             /// <summary>
   58+             /// Initializes a new instance of the <see cref="BattleGroundChatBuilder"/> class.
   59+             /// </summary>
   60+             /// <param name="msgtype">The msgtype.</param>
   61+             /// <param name="textId">The text id.</param>
   62+             /// <param name="source">The source.</param>
   63+             /// <param name="args">The args.</param>
   64+             BattleGroundChatBuilder(ChatMsg msgtype, int32 textId, Player const* source, va_list* args = nullptr)
   65+                 : i_msgtype(msgtype), i_textId(textId), i_source(source), i_args(args) {}
   66+             void operator()(WorldPacket& data, int32 loc_idx)
   67+             {
   68+                 char const* text = sObjectMgr.GetMangosString(i_textId, loc_idx);
   69+ 
   70+                 ObjectGuid sourceGuid = i_source ? i_source ->GetObjectGuid() : ObjectGuid();
   71+                 std::string sourceName = i_source ? i_source ->GetName() : "";
   72+ 
   73+                 if (i_args)
   74+                 {
   75+                     // we need copy va_list before use or original va_list will corrupted
   76+                     va_list ap;
   77+                     va_copy(ap, *i_args);
   78+ 
   79+                     char str [2048];
   80+                     vsnprintf(str, 2048, text, ap);
   81+                     va_end(ap);
   82+ 
   83+                     BuildMessageChatPacket(data, i_msgtype, &str[0], LANG_UNIVERSAL, CHAT_TAG_NONE, sourceGuid, sourceName.c_str());
   84+                 }
   85+                 else
   86+                 {
   87+                     BuildMessageChatPacket(data, i_msgtype, text, LANG_UNIVERSAL, CHAT_TAG_NONE, sourceGuid, sourceName.c_str(), sourceGuid, sourceName.c_str());
   88+                 }
   89+             }
   90+         private:
   91+             ChatMsg i_msgtype;
   92+             int32 i_textId;
   93+             Player const* i_source;
   94+             va_list* i_args;
   95+     };
